import React, { useContext } from 'react';
import { Container, Row, Col, Card } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import Layout from '../common/Layout';
import { AuthContext } from '../../App';
import { HomeworkContext } from '../../context/HomeworkContext';
import { isExactMatch } from '../../services/commonUtills/FormValidations';
import {
  FaUserGraduate,
  FaUserTie,
  FaBus,
  FaQuestionCircle,
  FaIdCard,
  FaCalendarAlt,
  FaUniversity,
  FaBuilding,
  FaCloudSun,
  FaBookOpen,
  FaClipboardCheck,
  FaBell,
  FaGraduationCap,
  FaCheck,
  FaTimes,
  FaUserCircle,
} from 'react-icons/fa';

function DashBoard() {
  const { stateAuth } = useContext(AuthContext);
  const { openHomework } = useContext(HomeworkContext);
  const navigate = useNavigate();
  const user = stateAuth?.user || {};
  const typ = (user.typ || '').toUpperCase();
  const cds = String(user.cds || '');
  const hasHomeworkPermission = cds
    .split(',')
    .map((value) => value.trim().toUpperCase())
    .includes('H_W_C');

  const getGreeting = () => {
    const hr = new Date().getHours();
    if (hr < 12) return 'Good Morning';
    if (hr < 17) return 'Good Afternoon';
    return 'Good Evening';
  };

  const displayName =
    user.stdnm || user.stfnm || user.drvnm || user.emlid || 'User';

  let cards = [];
  if (typ === 'STUDENT') {
    cards = [
      { label: 'Name', value: user.stdnm, icon: <FaUserGraduate /> },
      { label: 'Class', value: user.clsnm, icon: <FaUniversity /> },
      { label: 'Section', value: user.secnm, icon: <FaUniversity /> },
      { label: 'Roll Number', value: user.stdrolid, icon: <FaIdCard /> },
      { label: 'Academic Year', value: user.acdmcyr, icon: <FaCalendarAlt /> },
      { label: 'Mobile', value: user.mbleno, icon: <FaUserGraduate /> },
    ];
  } else if (typ === 'STAFF') {
    // cards = [
    //   { label: 'Staff Name', value: user.stfnm || displayName, icon: <FaUserTie /> },
    //   { label: 'Staff Roll ID', value: user.stfrolid, icon: <FaIdCard /> },
    //   { label: 'Institute Name', value: user.instnm, icon: <FaUniversity /> },
    //   { label: 'Branch Name', value: user.brcnm, icon: <FaBuilding /> },
    //   { label: 'Academic Year', value: user.acdmcyr, icon: <FaCalendarAlt /> },
    //   { label: 'Mobile', value: user.mbleno, icon: <FaUserTie /> },
    // ];
  } else if (typ === 'TRANSPORT') {
    cards = [
      { label: 'Driver Name', value: user.drvnm, icon: <FaBus /> },
      { label: 'From Route', value: user.frrt, icon: <FaBus /> },
      { label: 'To Route', value: user.tort, icon: <FaBus /> },
      { label: 'Vehicle No', value: user.velno, icon: <FaBus /> },
      { label: 'Vehicle Type', value: user.veltyp, icon: <FaBus /> },
      { label: 'Stops', value: user.stpno, icon: <FaBus /> },
    ];
  } else {
    cards = [
      { label: 'User', value: user.emlid || user.usrid, icon: <FaQuestionCircle /> },
    ];
  }

  return (
    <Layout>
      <Container className="py-4">
        <section className="user-welcome-panel">
          <div className="user-welcome-copy">
            <h3 className="user-welcome-title">
              {getGreeting()}, {displayName}!
            </h3>
            <p className="user-welcome-subtitle">Welcome to your institute user portal.</p>
          </div>
          <div className="user-welcome-icon-wrap" aria-hidden="true">
            <div className="user-welcome-icon">
              <FaCloudSun />
            </div>
          </div>
        </section>

        <Row>
          {cards.map((c, i) => (
            <Col md={6} xl={4} key={i}>
              <Card className="mb-3 shadow-sm">
                <Card.Body className="d-flex align-items-center gap-3">
                  <div
                    className="d-flex align-items-center justify-content-center"
                    style={{
                      width: '48px',
                      height: '48px',
                      borderRadius: '12px',
                      backgroundColor: '#eff6ff',
                      color: '#2f54eb',
                    }}
                  >
                    {c.icon}
                  </div>
                  <div>
                    <div className="text-muted" style={{ fontSize: '0.78rem' }}>
                      {c.label}
                    </div>
                    <div style={{ fontWeight: 700, color: '#1e293b' }}>
                      {c.value || '—'}
                    </div>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>

        {/* ── Quick Access ── */}
        <section className="dash-quick-section">
          <h6 className="dash-quick-title">Quick Access</h6>
          <div className="dash-quick-grid">

            {/* My Profile */}
            {isExactMatch(cds, 'I_N_U_S') && (
              <button
                className="dash-quick-card"
                onClick={() => navigate('/profile')}
              >
                <div className="dash-quick-icon" style={{ background: '#eff6ff', color: '#2f54eb' }}>
                  <FaUserCircle size={28} />
                </div>
                <span className="dash-quick-label">My Profile</span>
              </button>
            )}

            {/* Homework */}
            {isExactMatch(cds, 'H_W_M') && (
              <button
                className="dash-quick-card"
                onClick={openHomework}
                id="dash-homework-btn"
              >
                <div className="dash-quick-icon" style={{ background: '#f0fdf4', color: '#16a34a' }}>
                  <FaBookOpen size={28} />
                </div>
                <span className="dash-quick-label">Homework</span>
              </button>
            )}

          </div>
        </section>

      </Container>
    </Layout>
  );
}

export default DashBoard;
